let colors = ['#34bcd1', '#ffe042', '#ff6397', '#276496'];

let ctx;
let centerX, centerY;

function setup() {
	createCanvas(900, 900);
	rectMode(CENTER);
	colorMode(HSB, 360, 100, 100, 100);
	ctx = drawingContext;
	centerX = width / 2;
	centerY = height / 2;
	background('#f7fbfc');
	createPattern(width / 2, height / 2, width * 0.8, 10);
}

function createPattern(x, y, w, cellCount) {
	let cellSize = w / cellCount;
	for (let i = 0; i < cellCount; i++) {
		for (let j = 0; j < cellCount; j++) {
			let cellX = i * cellSize + (cellSize / 2) + (x - (w / 2));
			let cellY = j * cellSize + (cellSize / 2) + (y - (w / 2));
			let a = 0;
			if ((i % 2) == 1 && ((j % 2) == 0)) {
				a = PI / 2;
			}
			else if (((i % 2) == 0) && ((j % 2) == 1)) {
				a = -PI / 2;
			}
			else if (((i % 2) == 1) && ((j % 2) == 1)) {
				a = PI;
			}
			karambit(cellX, cellY, cellSize, a);
		}
	}
}

function karambit(x, y, w, ang) {
	let drawingType = int(random(4));

	push();
	translate(x, y);
	rotate(ang);
	strokeWeight(w * 0.02);
	stroke('#000');
	noFill();

	let aStep = (TAU / 360);
	beginShape();
	for (let a = PI * 1.5; a > PI / 2; a -= aStep) {
		vertex((w / 2) + (w / 2) * cos(a), (w / 2) * sin(a));
	}
	for (let a = 0; a < PI; a += aStep) {
		vertex((w / 2) * cos(a), (w / 2) + (w / 2) * sin(a));
	}
	for (let a = PI / 2; a > -PI / 2; a -= aStep) {
		vertex(-(w / 2) + (w / 4) * cos(a), (w / 4) + (w / 4) * sin(a));
	}
	for (let a = PI / 2; a < PI * 1.5; a += aStep) {
		vertex(-(w / 2) + (w / 4) * cos(a), -(w / 4) + (w / 4) * sin(a));
	}
	for (let a = PI; a > 0; a -= aStep) {
		vertex(-(w / 4) + (w / 4) * cos(a), -(w / 2) + (w / 4) * sin(a));
	}
	for (let a = PI; a < TAU; a += aStep) {
		vertex((w / 4) + (w / 4) * cos(a), -(w / 2) + (w / 4) * sin(a));
	}
	endShape();

	stroke('#000');
	if (drawingType == 0) {
		setStroke();
		fill(random(colors));
		circle(-w * 0.6, -w * 0.25, w * 0.2);
		setStroke();
		fill(random(colors));
		circle(w * 0.25, -w * 0.6, w * 0.2);
		setStroke();
		fill(random(colors));
		circle(-w * 0.175, -w * 0.075, w * 0.3);
		setStroke();
		fill(random(colors));
		circle(-w * 0.175, -w * 0.075, w * 0.1);
		setStroke();
		fill(random(colors));
		circle(-w * 0.1, w * 0.5, w * 0.4);
		noFill();
		setStroke();
		arc(0, w * 0.5, w * 0.8, w * 0.8, PI / 2, PI);
		let r1 = w * 0.38;
		let r2 = w * 0.42;
		for (let a = PI * 0.3; a < PI * 0.45; a += (TAU / 36)) {
			setStroke();
			line(r1 * cos(a), w * 0.5 + r1 * sin(a), r2 * cos(a), w * 0.5 + r2 * sin(a));
		}
	}
	else if (drawingType == 1) {
		setStroke();
		arc(0, w * 0.5, w * 0.8, w * 0.8, PI / 2, PI);
		let r1 = w * 0.3;
		let r2 = w * 0.45;
		for (let a = PI * 0.7; a < PI * 0.8; a += (TAU / 36)) {
			setStroke();
			line(r1 * cos(a), w * 0.5 + r1 * sin(a), r2 * cos(a), w * 0.5 + r2 * sin(a));
		}
		setStroke();
		line(-w * 0.6, -w * 0.4, -w * 0.6, -w * 0.1);
		line(-w * 0.6, -w * 0.15, -w * 0.2, -w * 0.15);
		setStroke();
		line(w * 0.1, -w * 0.525, w * 0.4, -w * 0.525);
		setStroke();
		fill(random(colors));
		circle(w * 0.25, -w * 0.625, w * 0.1);
		setStroke();
		line(w * 0.1, w * 0.9, w * 0.1, w * 0.6);
		fill(random(colors));
		circle(w * 0.1, w * 0.5, w * 0.05);
		fill(random(colors));
		circle(w * 0.25, w * 0.5, w * 0.05);

		setStroke();
		line(w * 0.25, w * 0.9, w * 0.25, w * 0.6);

		setStroke();
		noFill();
		waveLine(-w * 0.1, 0, -w * 0.1, w * 0.5, 4);
	}
	else if (drawingType == 2) {
		setStroke();
		beginShape();
		vertex(w * 0.1, -w * 0.6);
		vertex(w * 0.25, -w * 0.5);
		vertex(w * 0.4, -w * 0.6);
		endShape();

		fill(random(colors));
		setStroke();
		beginShape();
		vertex(-w * 0.25, w * 0.5);
		vertex(w * 0.25, w * 0.5);
		vertex(-w * 0.25, w * 0.9);
		endShape(CLOSE);

		setStroke();
		fill(random(colors));
		circle(-w * 0.4, w * 0.6, w * 0.05);
		setStroke();
		fill(random(colors));
		circle(w * 0.4, w * 0.6, w * 0.05);
		setStroke();
		fill(random(colors));
		circle(0, w * 0.9, w * 0.05);

		setStroke();
		arc(-w * 0.05, w * 0.25, w * 0.3, w * 0.3, PI / 2, PI * 1.5);
		line(-w * 0.05, -w * 0.1, -w * 0.05, w * 0.4);
		setStroke();
		line(0, -w * 0.2, -w * 0.4, -w * 0.2);
		setStroke();
		line(-w * 0.1, -w * 0.1, -w * 0.5, -w * 0.1);
		setStroke();
		noFill();
		waveLine(-w * 0.6, -w * 0.4, -w * 0.6, -w * 0.1, 3);
	}
	else if (drawingType == 3) {
		setStroke();
		arc(0, w * 0.525, w * 0.8, w * 0.8, 0, PI);
		fill(random(colors));
		circle(0, w * 0.68, w * 0.4);

		setStroke();
		noFill();
		waveLine(-w * 0.2, w * 0.2, -w * 0.2, -w * 0.1, 2);
		setStroke();
		beginShape();
		vertex(0, w * 0.2);
		vertex(-w * 0.1, w * 0.3);
		vertex(w * 0.05, w * 0.45);
		endShape();
		setStroke();
		fill(random(colors));
		ellipse(w * 0.25, -w * 0.6, w * 0.3, w * 0.15);
		setStroke();
		line(-w * 0.65, -w * 0.35, -w * 0.5, -w * 0.35);
		line(-w * 0.65, -w * 0.15, -w * 0.5, -w * 0.15);
	}
	pop();
}

function waveLine(x1, y1, x2, y2, num) {
	let dst = dist(x1, y1, x2, y2);
	let ang = atan2(y2 - y1, x2 - x1);
	let cNum = int(dst * 3);
	let waveNum = num * PI;
	let r = dst * 0.15;
	push();
	translate(x1, y1);
	rotate(ang);
	beginShape();
	for (let i = 0; i < cNum; i++) {
		let nrm = norm(i, 0, cNum - 1);
		let amp = r;
		let yy = lerp(0, amp, sin(nrm * waveNum));
		let xx = lerp(0, dst, nrm);
		vertex(xx, yy);
	}
	endShape();
	pop();
}

function setStroke() {
	strokeWeight(width / 10 * random(0.025, 0.015));
	stroke(random(colors));
	stroke('#000');
}

function setFill() {
	fill(random(colors));
}

